values ('jac-n55-reefer-2025', 'NED-25-0101', 'JAC N55 Refrigerated Van', 'JAC', 'N55', 'N-Series', 'Reefer · 14 ft', 'reefer', 2025, 'new'::public.truck_condition, 'available'::public.truck_availability, 3.5, 7300, '4x2', 'Cummins ISF 3.8L common-rail turbo-diesel', 3760, 154, 500, '6-speed manual', 'diesel', 'Euro 4', 3360, 0, 'White', 2480000, false, 'Cold-chain ready 3.5-tonne reefer with a Cummins heart and a cab built for long city shifts.', 'The N55 reefer pairs JAC''s N-Series cab with an insulated 14-ft body and transport refrigeration unit — ideal for food, pharma and frozen distribution across Metro Manila and the provinces. Cummins ISF power gives you strong low-end torque for loaded starts on flyovers.', array['Cummins ISF engine', 'Insulated FRP body', 'Transport refrigeration unit', 'ABS + exhaust brake', 'Air-conditioned cab', 'Tilt cab for easy service']::text[], '{"Body length":"14 ft","Temp range":"-18 °C to +8 °C","Fuel tank":"120 L","Tyres":"7.50R16"}'::jsonb, (select id from public.branches where slug = 'north-edsa'), true, true)
