values ('jac-t8-pro-4x4-2025', 'BON-25-0207', 'JAC T8 Pro 2.0 CTi 4x4', 'JAC', 'T8 Pro', 'T-Series Pickup', 'Double cab · 4x4 · MT', 'pickup', 2025, 'new'::public.truck_condition, 'available'::public.truck_availability, 1, 3050, '4x4', '2.0L CTi turbo-diesel', 1999, 139, 320, '6-speed manual', 'diesel', 'Euro 5', 3090, 0, 'Navy Blue', 1398000, false, 'A one-tonne workhorse that cleans up for Sunday — shift-on-the-fly 4x4, Euro 5 diesel.', 'The T8 Pro is JAC''s do-everything double-cab pickup: one-tonne payload, a 2.0L CTi turbo-diesel and shift-on-the-fly 4x4 for site roads and flood season. Comes with a full infotainment suite and a 360° camera.', array['Shift-on-the-fly 4x4', '360° camera', 'Rear differential lock', 'Hill descent control', '9-inch touchscreen', 'Dual front airbags']::text[], '{"Ground clearance":"220 mm","Wading depth":"600 mm","Bed size":"1520 × 1520 × 470 mm","Fuel tank":"76 L"}'::jsonb, (select id from public.branches where slug = 'a-bonifacio'), true, true)
