values ('jac-gallop-k5-8x4-cargo-2025', 'PAM-25-0012', 'JAC Gallop K5 8x4 High-side Cargo', 'JAC', 'Gallop K5', 'Gallop', '8x4 · 12-wheeler', 'cargo_high_side', 2025, 'new'::public.truck_condition, 'available'::public.truck_availability, 25, 31000, '8x4', 'Weichai WP10 9.7L turbo-diesel', 9726, 336, 1350, 'Fast 12-speed manual', 'diesel', 'Euro 4', 6100, 0, 'Graphite', null, true, 'Twelve wheels, 25 tonnes, built for quarry, rice and cement runs up and down the expressway.', 'The Gallop K5 8x4 is our heavy hauler: a 9.7L Weichai engine with 1,350 Nm, a Fast 12-speed gearbox and a reinforced double-layer frame. Configured with a high-side cargo body for bulk agricultural and construction loads.', array['Weichai WP10 engine', 'Fast 12-speed gearbox', 'Double-layer frame', 'Air-suspended seat', 'Engine brake', 'Sleeper cab']::text[], '{"Body length":"9.6 m","Fuel tank":"400 L","Tyres":"12.00R20","Rear axle":"Hub reduction, 13 T"}'::jsonb, (select id from public.branches where slug = 'pampanga'), true, true)
