values ('pms-10000', '10,000 km Preventive Maintenance', 'preventive_maintenance'::public.service_category, 'The essentials, on schedule: oil, filters, 40-point inspection.', 'Engine oil and oil filter change, fuel water-separator drain, 40-point safety inspection, brake adjustment, fluid top-ups and a printed health report.', array['Engine oil + genuine oil filter', 'Fuel/water separator drain', 'Brake adjustment', '40-point inspection', 'Fluid top-up', 'Health report']::text[], 2.5, null, 10000, 6, true, 1)
